    private static AccessDecision? Validate(Principal principal, Resource resource, AccessRequest request)
    {
        var contextFailure = ValidateContext(principal, resource, request);
        return contextFailure ?? ValidateChallenge(principal, request);
    }

    private static AccessDecision? ValidateContext(Principal principal, Resource resource, AccessRequest request)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Deny("invalid-identity");
        if (principal.Suspended)
            return Deny("principal-suspended");
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Deny("tenant-mismatch");
        if (resource.Locked && request.Action != "read")
            return Deny("resource-locked");

        return null;
    }

    private static AccessDecision? ValidateChallenge(Principal principal, AccessRequest request)
    {
        if (request.MinuteOfDay is < 0 or > 1439)
            return Deny("invalid-time");
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Deny("challenge-required");

        return null;
    }

    private static Permissions GetPermissions(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new Permissions(administrator, operatorRole, auditor, owner, delegated);
    }

    private static AccessDecision EvaluateAccess(Resource resource, AccessRequest request, Permissions permissions)
    {
        if (request.BreakGlass)
            return EvaluateBreakGlass(request, permissions);

        var restrictionFailure = EvaluateRestrictions(resource, request);
        if (restrictionFailure is not null)
            return restrictionFailure;

        var authorizationFailure = EvaluateAction(request.Action, permissions);
        if (authorizationFailure is not null)
            return authorizationFailure;

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            permissions.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static AccessDecision EvaluateBreakGlass(AccessRequest request, Permissions permissions)
    {
        if (!permissions.Administrator || !request.StrongAuthentication)
            return Deny("invalid-break-glass");

        return new AccessDecision(true, "break-glass", true);
    }

    private static AccessDecision? EvaluateRestrictions(Resource resource, AccessRequest request)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Deny("strong-authentication-required");
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Deny("trusted-network-required");

        return null;
    }

    private static AccessDecision? EvaluateAction(string action, Permissions permissions)
    {
        return action switch
        {
            "delete" when !permissions.Administrator => Deny("administrator-required"),
            "write" when !CanWrite(permissions) => Deny("write-not-authorised"),
            "read" when !CanRead(permissions) => new AccessDecision(false, "read-not-authorised", false),
            "read" or "write" or "delete" => null,
            _ => Deny("unknown-action")
        };
    }

